"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2952],{14565:e=>{e.exports=JSON.parse('{"functions":[{"name":"Initialize","desc":"Initialises (or resets) all internal fuel state and wires up the server-side\\npacket handlers for refuelling and brake toggling.\\n\\nMust be called exactly once by the owning server script before any client\\nrequests arrive.  The function:\\n- Resets fuel to `TrainConfig.INITIAL_FUEL` and sets `isBraked` to\\n  `TrainConfig.INITIAL_BRAKED`.\\n- Binds `Packets.ReqRefuelTrain.OnServerInvoke` and\\n  `Packets.ReqToggleBrake.OnServerInvoke`.\\n- Registers a `JoinSync` sender so each client receives the current\\n  snapshot once it announces readiness (see docs/reference/join-sync.md).\\n- Fires the initial `TrainStateSync` broadcast and schedules the first\\n  deterministic transition.","params":[],"returns":[],"function_type":"static","source":{"line":337,"path":"src/ServerStorage/SharedModules/TrainFuelManager.luau"}},{"name":"SetJumpFreeze","desc":"Suspends fuel drain and fuel damage for the duration of a jump. Both edges\\ncall `commitEvent()` so the algebraic model re-snapshots under the old rate\\nbefore switching \u2014 without it, every client\'s extrapolated bar would keep\\ndraining straight through the transition.\\n\\nThe `not hasStarted or TrainGameOver.HasFired()` guard applies ONLY to the\\nfreeze edge (`frozen == true`): it exists so a jump signal can\'t disturb the\\npre-game freeze or restart a settled game-over timer. It must NOT guard the\\nunfreeze edge \u2014 do not \\"restore symmetry\\" by moving it above the `if frozen`\\ncheck. If it did, `isJumping` could get set `true` by a freeze that then\\ncompletes after game-over fires, and the corresponding unfreeze would be\\nsilently dropped, leaving `isJumping` stuck `true` forever. That\'s inert\\ntoday (the round is dead and `HasFired()` independently blocks\\n`ApplyFuelDamage`), but would silently zero fuel drain/damage after a future\\n`TrainGameOver.Reset()`-based round restart. Unfreezing after game over is\\nalways safe: `commitEvent()` just recomputes the rate, which `rateForState()`\\nstill pins to 0 via `isStalled`, and `onGameOver` is idempotent.","params":[{"name":"frozen","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":396,"path":"src/ServerStorage/SharedModules/TrainFuelManager.luau"}},{"name":"ApplyFuelDamage","desc":"Combat fuel-damage sink, called by `TrainShieldManager` once the shield is\\ndown. `amount` is fuel units already converted by `TrainConfig.FUEL_DAMAGE_FACTOR`.\\nIf the hit leaves fuel above 0 it commits the new level (the natural stall\\ntimer simply shortens). Reducing fuel to 0 this way is an **immediate** game\\nover (`FUEL_DESTROYED_BY_ATTACK`) \u2014 no `GAME_OVER_DELAY` grace. No-op before\\nthe round is live or after game over has fired.","params":[{"name":"amount","desc":"","lua_type":"number"},{"name":"_source","desc":"","lua_type":"any?"}],"returns":[],"function_type":"static","source":{"line":416,"path":"src/ServerStorage/SharedModules/TrainFuelManager.luau"}}],"properties":[],"types":[],"name":"TrainFuelManager","desc":"Global, server-authoritative module that manages the train\'s fuel level\\n(a scalar in the range 0\u2013`TrainConfig.MAX_FUEL`).\\n\\nFuel is computed algebraically from the last recorded event rather than by a\\nper-frame loop: each state transition (init, refuel, brake toggle, stall,\\ngame-over) snapshots the current fuel, updates the active drain rate, and\\nre-schedules the next deterministic transition via `task.delay` guarded by a\\ngeneration nonce.  Clients receive a `TrainStateSync` packet containing the\\nexact server timestamp and drain rate so they can predict the bar locally\\nwithout polling.\\n\\nThe module operates in three named states:\\n- **Running** \u2014 train is moving; fuel drains at `RUNNING_DRAIN_PER_SEC`.\\n- **Braked** \u2014 brake lever is engaged; fuel drains at the slower\\n  `STOPPED_DRAIN_PER_SEC` and junk floats at reduced speed.\\n- **Stalled** \u2014 fuel reached 0; drain stops and a game-over timer starts.\\n\\nState transitions also fire `Signals.SetTrainState` so `JunkService` keeps\\njunk speed and spawn rate in sync.","realm":["Server"],"source":{"line":60,"path":"src/ServerStorage/SharedModules/TrainFuelManager.luau"}}')}}]);